#!/usr/bin/env sh
# Senzu Theme for fzf: Senzu Dusk Light
# Generated by senzu
#
# Source this file in your shell rc to apply (zsh/bash):
#
#   [ -f ~/.config/fzf/senzu-dusk-light.sh ] && . ~/.config/fzf/senzu-dusk-light.sh
#
# It appends the Senzu --color spec to FZF_DEFAULT_OPTS, preserving any other
# fzf options you set. To switch variants, source a different senzu fzf file
# instead (fzf merges --color flags, last one wins per element).

export FZF_DEFAULT_OPTS="${FZF_DEFAULT_OPTS:+$FZF_DEFAULT_OPTS }--color=fg:#2a2633,bg:#f6f3fe,hl:#876820,fg+:#2a2633,bg+:#cec8e5,hl+:#876820,info:#695e9d,border:#d4d2e0,prompt:#2952a3,pointer:#632b7a,marker:#386014,spinner:#6a4abd,header:#655f73,gutter:#cec8e5,preview-fg:#2a2633,preview-bg:#f6f3fe"
